fn to_uppercase(str1: &Vec<char>) -> Vec<char> {
    let mut result = Vec::with_capacity(str1.len());

    for &ch in str1.iter() {
        if ('a'..='z').contains(&ch) {
            // Convert lowercase ASCII letter to uppercase by shifting
            let upper = ((ch as u8) - b'a' + b'A') as char;
            result.push(upper);
        } else {
            // Leave character unchanged if not lowercase ASCII letter
            result.push(ch);
        }
    }

    result
}